package message

import (
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/free5gc/nas/ie"
)

func TestAuthResultUnmarshalBinary(t *testing.T) {
	t.Parallel()

	testCases := []struct {
		name     string
		input    []byte
		expected Message
	}{
		{
			name: "EAP AuthResult",
			input: []byte{
				0x7e, 0x00, 0x5a, 0x00, 0x00, 0x6c, 0x01, 0x01, 0x00, 0x6c, 0x32, 0x01,
				0x00, 0x00, 0x18, 0x01, 0x00, 0x01, 0x17, 0x09, 0x00, 0x20, 0x35, 0x47, 0x3a, 0x6d, 0x6e, 0x63,
				0x30, 0x39, 0x33, 0x2e, 0x6d, 0x63, 0x63, 0x32, 0x30, 0x38, 0x2e, 0x33, 0x67, 0x70, 0x70, 0x6e,
				0x65, 0x74, 0x77, 0x6f, 0x72, 0x6b, 0x2e, 0x6f, 0x72, 0x67, 0x01, 0x05, 0x00, 0x00, 0x00, 0x01,
				0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f, 0x02, 0x05,
				0x00, 0x00, 0x62, 0x11, 0x01, 0x9c, 0xa0, 0x8a, 0x80, 0x00, 0xe4, 0x47, 0x2c, 0xc0, 0x8c, 0x69,
				0x65, 0x71, 0x0b, 0x05, 0x00, 0x00, 0xac, 0x07, 0x69, 0x3f, 0xdd, 0x2e, 0x46, 0x88, 0xc2, 0xbc,
				0x57, 0x19, 0x57, 0x56, 0x83, 0x4d, 0x38, 0x02, 0x00, 0x00,
			},
			expected: &AuthResult{
				Ngksi: &ie.NASKeySetId{
					Tsc: ie.SecCtxTypeNative,
					Ksi: 0,
				},
				ABBA: &ie.ABBA{
					Abba: []byte{0x00, 0x00},
				},
				EAPMsg: &ie.EAPMsg{
					Eap: []byte{
						0x01, 0x01, 0x00, 0x6c, 0x32, 0x01, 0x00, 0x00, 0x18, 0x01, 0x00, 0x01, 0x17, 0x09, 0x00, 0x20,
						0x35, 0x47, 0x3a, 0x6d, 0x6e, 0x63, 0x30, 0x39, 0x33, 0x2e, 0x6d, 0x63, 0x63, 0x32, 0x30, 0x38,
						0x2e, 0x33, 0x67, 0x70, 0x70, 0x6e, 0x65, 0x74, 0x77, 0x6f, 0x72, 0x6b, 0x2e, 0x6f, 0x72, 0x67,
						0x01, 0x05, 0x00, 0x00, 0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b,
						0x0c, 0x0d, 0x0e, 0x0f, 0x02, 0x05, 0x00, 0x00, 0x62, 0x11, 0x01, 0x9c, 0xa0, 0x8a, 0x80, 0x00,
						0xe4, 0x47, 0x2c, 0xc0, 0x8c, 0x69, 0x65, 0x71, 0x0b, 0x05, 0x00, 0x00, 0xac, 0x07, 0x69, 0x3f,
						0xdd, 0x2e, 0x46, 0x88, 0xc2, 0xbc, 0x57, 0x19, 0x57, 0x56, 0x83, 0x4d,
					},
				},
			},
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			msg := new(AuthResult)
			err := msg.UnmarshalBinary(tc.input)
			require.NoError(t, err)
			require.Equal(t, tc.expected, msg)
		})
	}
}

